// WF1 — normalise n'importe quel formulaire de landing page vers le contrat
// attendu par POST /api/webhooks/leads/inbound du CRM.
// Le corps signe DOIT etre exactement le corps envoye -> on serialise ici une
// seule fois dans `payload`. NOUVEAU : anti-rejeu -> on signe `ts.payload` et on
// envoie l'en-tete X-Timestamp (le CRM l'exige en production).

const ACTIVITIES = ['urgence', 'nettoyage', 'nettoyage_difficile', 'enr', 'renovation', 'debarras', 'demenagement', 'diogene'];
// Pieges de vocabulaire : le metier dit « depannage », le slug est
// « urgence ». Un formulaire qui envoie le mot naturel tombait dans le repli
// « nettoyage » et partait a la mauvaise adresse. On tolere donc les synonymes
// plutot que de compter sur la memoire de celui qui integre le formulaire.
const ACT_ALIAS = {
  depannage: 'urgence', depannage_urgence: 'urgence', urgent: 'urgence',
  depanage: 'urgence', intervention_urgente: 'urgence',
  demenagement_particulier: 'demenagement', demenager: 'demenagement',
  debarras_maison: 'debarras', debaras: 'debarras',
  diogenes: 'diogene', syndrome_diogene: 'diogene', insalubrite: 'diogene',
  nettoyage_apres_deces: 'nettoyage_difficile', apres_deces: 'nettoyage_difficile',
  renovation_batiment: 'renovation', photovoltaique: 'enr', solaire: 'enr',
};

const ACTIVITY_LABEL = {
  urgence: 'Depannage',
  nettoyage: 'Nettoyage',
  nettoyage_difficile: 'Nettoyage difficile',
  enr: 'Energies renouvelables',
  renovation: 'Renovation',
  debarras: 'Debarras',
  demenagement: 'Demenagement',
  diogene: 'Nettoyage Diogene',
};

const SOURCES = ['google_ads', 'meta_ads', 'site_web', 'telephone', 'recommandation'];

const SRC_ALIAS = {
  google: 'google_ads', 'google-ads': 'google_ads', googleads: 'google_ads', adwords: 'google_ads',
  facebook: 'meta_ads', meta: 'meta_ads', instagram: 'meta_ads', fb: 'meta_ads',
  site: 'site_web', web: 'site_web', website: 'site_web', formulaire: 'site_web',
  phone: 'telephone', tel: 'telephone',
  reco: 'recommandation', parrainage: 'recommandation',
};

const DEFAULT_ACTIVITY = 'nettoyage';
const DEFAULT_SOURCE = 'site_web';

const out = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json.query || item.json || {};

  const pick = (...keys) => {
    for (const k of keys) {
      const v = b[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };
  const truthy = (s) => ['true', '1', 'oui', 'yes', 'on'].includes(s.toLowerCase());

  let phone = pick('phone', 'telephone', 'tel', 'mobile', 'numero').replace(/[^\d+]/g, '');
  if (/^0\d{9}$/.test(phone)) phone = '+33' + phone.slice(1);

  let activity = pick('activity_slug', 'activity', 'prestation', 'service', 'metier')
    .toLowerCase().trim().replace(/[\s-]+/g, '_');
  activity = ACT_ALIAS[activity] || activity;
  if (!ACTIVITIES.includes(activity)) activity = DEFAULT_ACTIVITY;

  let source = pick('source_slug', 'source', 'utm_source').toLowerCase();
  source = SRC_ALIAS[source] || source;
  if (!SOURCES.includes(source)) source = DEFAULT_SOURCE;

  const isCompany = truthy(pick('is_company', 'societe', 'pro'));
  const num = (s) => { const n = Number(String(s).replace(',', '.')); return Number.isFinite(n) && n > 0 ? n : null; };

  let firstName = pick('first_name', 'prenom', 'firstname', 'fname');
  let lastName = pick('last_name', 'nom', 'lastname', 'lname');
  if (!firstName && lastName.includes(' ')) {
    const nameParts = lastName.split(/\s+/);
    firstName = nameParts.shift();
    lastName = nameParts.join(' ');
  }

  const surfaceMatch = pick('surface_m2', 'surface', 'm2', 'superficie').match(/\d+/);
  const surfaceM2 = surfaceMatch ? num(surfaceMatch[0]) : null;

  const lead = {
    external_id: pick('external_id') || `lp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    is_company: isCompany,
    first_name: firstName,
    last_name: lastName,
    company_name: pick('company_name', 'societe_nom', 'company', 'entreprise') || null,
    email: pick('email', 'mail', 'e-mail').toLowerCase(),
    phone: phone,
    address_line: pick('address_line', 'adresse', 'address', 'rue'),
    postal_code: pick('postal_code', 'code_postal', 'cp', 'zip'),
    city: pick('city', 'ville'),
    activity_slug: activity,
    source_slug: source,
    lp: pick('lp', 'lp_token', 'source_token') || null,
    estimated_amount: num(pick('estimated_amount', 'budget', 'montant')),
    surface_m2: surfaceM2,
    type_service: pick('type_service', 'service_type', 'type_prestation', 'formule') || null,
    is_extreme: truthy(pick('is_extreme', 'urgent', 'urgence_extreme')),
    gclid: pick('gclid') || null,
    utm_source: pick('utm_source') || null,
    utm_campaign: pick('utm_campaign') || null,
    utm_medium: pick('utm_medium') || null,
    utm_term: pick('utm_term') || null,
    utm_content: pick('utm_content') || null,
    notes: pick('notes', 'message', 'commentaire', 'demande', 'description'),
  };

  // ── Provenance : d'ou vient la demande ────────────────────────────
  // L'en-tete Origin donne le SITE (https://demenagementproservices.com),
  // le Referer donne la PAGE exacte. Le champ du formulaire, s'il existe,
  // prime sur les deux : c'est le seul que l'integrateur maitrise.
  const headers = item.json.headers || {};
  const siteOrigin = String(headers.origin || headers.Origin || '').trim();
  const refererUrl = String(headers.referer || headers.Referer || '').trim();
  const pageUrl = pick('source_url', 'page_url', 'form_url', 'page_origine', 'referrer') || refererUrl || siteOrigin;
  const siteLabel = siteOrigin.replace(/^https?:\/\//, '') || '-';

  // Le CRM stocke cette URL (chiffree, visible admin/planif seulement).
  // Elle n'etait JAMAIS transmise jusqu'ici : le champ existait cote CRM,
  // rien ne le remplissait.
  lead.source_url = pageUrl || null;

  // ── Corps de l'e-mail ─────────────────────────────────────────────
  const esc = (v) => String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  const C = {
    bleu: '#0050c7', encre: '#1a1a1a', gris: '#6b7280',
    bord: '#e4e4e7', fond: '#f8f9fb',
  };

  // Une ligne « libelle / valeur ». Les valeurs vides sont omises : un
  // e-mail rempli de tirets ne se lit pas.
  const ligne = (label, valeur, html) => {
    const v = String(valeur == null ? '' : valeur).trim();
    if (!v) return '';
    return '<tr>'
      + '<td style="padding:6px 12px 6px 0;color:' + C.gris + ';font-size:13px;white-space:nowrap;vertical-align:top">' + esc(label) + '</td>'
      + '<td style="padding:6px 0;font-size:14px;color:' + C.encre + ';vertical-align:top">' + (html || esc(v)) + '</td>'
      + '</tr>';
  };

  const bloc = (titre, lignes) => {
    const corps = lignes.filter(Boolean).join('');
    if (!corps) return '';
    return '<div style="margin-top:22px">'
      + '<div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:' + C.gris + ';border-bottom:1px solid ' + C.bord + ';padding-bottom:6px;margin-bottom:8px">' + esc(titre) + '</div>'
      + '<table cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse">' + corps + '</table>'
      + '</div>';
  };

  const nomComplet = lead.is_company
    ? (lead.company_name || '')
    : `${lead.first_name} ${lead.last_name}`.trim();

  const tel = lead.phone
    ? '<a href="tel:' + esc(lead.phone) + '" style="color:' + C.bleu + ';text-decoration:none;font-weight:700">' + esc(lead.phone) + '</a>'
    : '';
  const mail = lead.email
    ? '<a href="mailto:' + esc(lead.email) + '" style="color:' + C.bleu + ';text-decoration:none">' + esc(lead.email) + '</a>'
    : '';

  const adresse = [lead.address_line, [lead.postal_code, lead.city].filter(Boolean).join(' ')]
    .filter(Boolean).join('<br/>');

  // ── Tous les champs du formulaire, sans exception ─────────────────
  // Le normaliseur ne retient qu'une partie des champs ; cette section
  // garantit qu'aucune information saisie par le client ne se perd, meme
  // celles que le CRM ne sait pas encore stocker.
  const TECHNIQUES = new Set(['lp', 'lp_token', 'source_token', 'external_id',
    'gclid', 'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
    'source_url', 'page_url', 'form_url', 'page_origine', 'referrer', 'activity_slug']);
  const brut = Object.keys(b)
    .filter((k) => !TECHNIQUES.has(k) && String(b[k] ?? '').trim() !== '')
    .map((k) => ligne(k, b[k]))
    .join('');

  const marketing = [
    ligne('Campagne', lead.utm_campaign),
    ligne('Source UTM', lead.utm_source),
    ligne('Support', lead.utm_medium),
    ligne('Mot-cle', lead.utm_term),
    ligne('Contenu', lead.utm_content),
    ligne('Google Ads', lead.gclid ? 'clic identifie (gclid present)' : ''),
  ].filter(Boolean).join('');

  const horodatage = new Date().toLocaleString('fr-FR', {
    timeZone: 'Europe/Paris', dateStyle: 'short', timeStyle: 'short',
  });

  const emailHtml =
    '<div style="background:' + C.fond + ';padding:24px 12px">'
    + '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;background:#fff;border-radius:10px;overflow:hidden;border:1px solid ' + C.bord + '">'

    // Bandeau
    + '<div style="background:' + C.bleu + ';color:#fff;padding:20px 24px">'
    + '<div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;opacity:.8">Nouveau lead</div>'
    + '<div style="font-size:21px;font-weight:700;margin-top:2px">' + esc(ACTIVITY_LABEL[activity] || 'Nettoyage') + '</div>'
    + '<div style="font-size:12px;opacity:.85;margin-top:6px">' + esc(horodatage) + (siteLabel !== '-' ? ' &middot; ' + esc(siteLabel) : '') + '</div>'
    + '</div>'

    + '<div style="padding:4px 24px 24px">'

    + bloc('Client', [
        ligne(lead.is_company ? 'Societe' : 'Nom', nomComplet),
        ligne('Telephone', lead.phone, tel),
        ligne('E-mail', lead.email, mail),
        ligne('Adresse', adresse ? 'x' : '', adresse),
      ])

    + bloc('Demande', [
        ligne('Activite', ACTIVITY_LABEL[activity] || activity),
        ligne('Prestation', lead.type_service),
        ligne('Surface', lead.surface_m2 ? lead.surface_m2 + ' m2' : ''),
        ligne('Budget', lead.estimated_amount ? lead.estimated_amount + ' EUR' : ''),
        ligne('Demande extreme', lead.is_extreme ? 'OUI' : ''),
        ligne('Message', lead.notes, esc(lead.notes).replace(/\n/g, '<br/>')),
      ])

    + bloc('Provenance', [
        ligne('Site', siteLabel),
        ligne('Page', pageUrl),
        ligne('Canal', lead.source_slug),
        ligne('Landing page', lead.lp),
      ].concat(marketing ? [marketing] : []))

    + (brut ? bloc('Detail complet du formulaire', [brut]) : '')

    // Bouton CRM — les deux marqueurs sont remplaces par le noeud e-mail,
    // qui seul connait l'identifiant attribue par le CRM.
    + '<div style="margin-top:26px;text-align:center">'
    + '<a href="https://crmoptimum.com/leads/%%CRM_ID%%" style="display:inline-block;background:' + C.bleu + ';color:#fff;text-decoration:none;font-weight:700;font-size:14px;padding:12px 26px;border-radius:8px">Ouvrir la fiche dans le CRM</a>'
    + '<div style="font-size:12px;color:' + C.gris + ';margin-top:8px">Reference %%CRM_REF%%</div>'
    + '</div>'

    + '</div></div></div>';

  const missing = [];
  if (!lead.phone) missing.push('phone');
  if (isCompany && !lead.company_name) missing.push('company_name');
  if (!isCompany && !`${lead.first_name} ${lead.last_name}`.trim()) missing.push('nom');

  // NOUVEAU : timestamp (anti-rejeu) + chaine signee = `ts.payload`.
  const ts = Math.floor(Date.now() / 1000);
  const payload = JSON.stringify(lead);
  out.push({
    json: {
      ts: ts,
      payload: payload,
      signedString: ts + '.' + payload,
      lead: lead,
      // Libelle lisible pour l'e-mail. Volontairement HORS de `lead` :
      // le payload signe doit rester exactement le contrat du CRM.
      activity_label: ACTIVITY_LABEL[activity] || 'Nettoyage',
      site_origin: siteLabel,
      page_url: pageUrl,
      email_html: emailHtml,
      valid: missing.length === 0,
      missing: missing.join(', '),
    },
  });
}

return out;
